-- Permission vocabulary and system roles of the schedule module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the schedule permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('schedule:create'::text, 'schedule'::text, 'create'::text, 'Create schedule'::text),
            ('schedule:delete'::text, 'schedule'::text, 'delete'::text, 'Delete schedule'::text),
            ('schedule:purge'::text, 'schedule'::text, 'purge'::text, 'Purge schedule'::text),
            ('schedule:read'::text, 'schedule'::text, 'read'::text, 'Read schedule'::text),
            ('schedule:restore'::text, 'schedule'::text, 'restore'::text, 'Restore schedule'::text),
            ('schedule:update'::text, 'schedule'::text, 'update'::text, 'Update schedule'::text),
            ('schedule_employee:create'::text, 'schedule_employee'::text, 'create'::text, 'Create schedule employee'::text),
            ('schedule_employee:delete'::text, 'schedule_employee'::text, 'delete'::text, 'Delete schedule employee'::text),
            ('schedule_employee:purge'::text, 'schedule_employee'::text, 'purge'::text, 'Purge schedule employee'::text),
            ('schedule_employee:read'::text, 'schedule_employee'::text, 'read'::text, 'Read schedule employee'::text),
            ('schedule_employee:restore'::text, 'schedule_employee'::text, 'restore'::text, 'Restore schedule employee'::text),
            ('schedule_employee:update'::text, 'schedule_employee'::text, 'update'::text, 'Update schedule employee'::text),
            ('schedule_organization:create'::text, 'schedule_organization'::text, 'create'::text, 'Create schedule organization'::text),
            ('schedule_organization:delete'::text, 'schedule_organization'::text, 'delete'::text, 'Delete schedule organization'::text),
            ('schedule_organization:purge'::text, 'schedule_organization'::text, 'purge'::text, 'Purge schedule organization'::text),
            ('schedule_organization:read'::text, 'schedule_organization'::text, 'read'::text, 'Read schedule organization'::text),
            ('schedule_organization:restore'::text, 'schedule_organization'::text, 'restore'::text, 'Restore schedule organization'::text),
            ('schedule_organization:update'::text, 'schedule_organization'::text, 'update'::text, 'Update schedule organization'::text),
            ('schedule_weekday:create'::text, 'schedule_weekday'::text, 'create'::text, 'Create schedule weekday'::text),
            ('schedule_weekday:delete'::text, 'schedule_weekday'::text, 'delete'::text, 'Delete schedule weekday'::text),
            ('schedule_weekday:purge'::text, 'schedule_weekday'::text, 'purge'::text, 'Purge schedule weekday'::text),
            ('schedule_weekday:read'::text, 'schedule_weekday'::text, 'read'::text, 'Read schedule weekday'::text),
            ('schedule_weekday:restore'::text, 'schedule_weekday'::text, 'restore'::text, 'Restore schedule weekday'::text),
            ('schedule_weekday:update'::text, 'schedule_weekday'::text, 'update'::text, 'Update schedule weekday'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('schedule:create'::text, 'schedule'::text, 'create'::text, 'Create schedule'::text),
            ('schedule:delete'::text, 'schedule'::text, 'delete'::text, 'Delete schedule'::text),
            ('schedule:purge'::text, 'schedule'::text, 'purge'::text, 'Purge schedule'::text),
            ('schedule:read'::text, 'schedule'::text, 'read'::text, 'Read schedule'::text),
            ('schedule:restore'::text, 'schedule'::text, 'restore'::text, 'Restore schedule'::text),
            ('schedule:update'::text, 'schedule'::text, 'update'::text, 'Update schedule'::text),
            ('schedule_employee:create'::text, 'schedule_employee'::text, 'create'::text, 'Create schedule employee'::text),
            ('schedule_employee:delete'::text, 'schedule_employee'::text, 'delete'::text, 'Delete schedule employee'::text),
            ('schedule_employee:purge'::text, 'schedule_employee'::text, 'purge'::text, 'Purge schedule employee'::text),
            ('schedule_employee:read'::text, 'schedule_employee'::text, 'read'::text, 'Read schedule employee'::text),
            ('schedule_employee:restore'::text, 'schedule_employee'::text, 'restore'::text, 'Restore schedule employee'::text),
            ('schedule_employee:update'::text, 'schedule_employee'::text, 'update'::text, 'Update schedule employee'::text),
            ('schedule_organization:create'::text, 'schedule_organization'::text, 'create'::text, 'Create schedule organization'::text),
            ('schedule_organization:delete'::text, 'schedule_organization'::text, 'delete'::text, 'Delete schedule organization'::text),
            ('schedule_organization:purge'::text, 'schedule_organization'::text, 'purge'::text, 'Purge schedule organization'::text),
            ('schedule_organization:read'::text, 'schedule_organization'::text, 'read'::text, 'Read schedule organization'::text),
            ('schedule_organization:restore'::text, 'schedule_organization'::text, 'restore'::text, 'Restore schedule organization'::text),
            ('schedule_organization:update'::text, 'schedule_organization'::text, 'update'::text, 'Update schedule organization'::text),
            ('schedule_weekday:create'::text, 'schedule_weekday'::text, 'create'::text, 'Create schedule weekday'::text),
            ('schedule_weekday:delete'::text, 'schedule_weekday'::text, 'delete'::text, 'Delete schedule weekday'::text),
            ('schedule_weekday:purge'::text, 'schedule_weekday'::text, 'purge'::text, 'Purge schedule weekday'::text),
            ('schedule_weekday:read'::text, 'schedule_weekday'::text, 'read'::text, 'Read schedule weekday'::text),
            ('schedule_weekday:restore'::text, 'schedule_weekday'::text, 'restore'::text, 'Restore schedule weekday'::text),
            ('schedule_weekday:update'::text, 'schedule_weekday'::text, 'update'::text, 'Update schedule weekday'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
